// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ZYTConfig
 * @notice 全局参数中心（v9 口径，2026-09-24 拍板）。
 *         v9 范式：弃 GST，USDT↔ZYT 单币直换，真实 PancakeSwap V2 pair 为唯一底池。
 *         - 删除 GST 相关参数与地址
 *         - 删除买入白名单（v9 买币门槛 = 阶段门控 + 买额 1:1）
 *         - 新增 swapFeeBps（Pancake V2 0.25% 交易费）、deflationLpRate（每日报销初始 LP 2%）
 *         部署后 owner 应转移给 Gnosis Safe 多签。
 */
contract ZYTConfig is Ownable {
    // ---------- 数值参数（基点 = 万分比） ----------
    uint256 public zytMaxSupply = 2_100_000_000e18; // 21 亿（初始底池全量，一次铸出）
    uint256 public minDeposit = 100e18;             // 最小入金 100U
    uint256 public maxDeposit = 500e18;             // 单笔上限 500U（可调）
    uint256 public marketingRate = 4000;            // 40% 生态（30% 代数 + 10% 技术）
    uint256 public poolRate = 6000;                 // 60% 组 LP 凭证销毁
    uint256 public powerRate = 10000;               // 算力倍率 1.0（1000U → 1000 算力）
    uint256 public dailyCompoundRate = 100;         // 日复利 1%
    uint256 public dynamicQuotaMul = 5;             // 动态额度 = 入金 × 5（加速释放载体）
    uint256 public staticExitMul = 2;               // 静态 2 倍出局
    uint256 public deflationRate = 200;             // 每日通缩 2%（1% 销毁 + 1% 分红）
    uint256 public deflationFloor = 5_000_000e18;   // 通缩至 500 万枚停止
    uint256 public baseSlippage = 500;              // 基础滑点 5%
    uint256 public slippageTier1 = 1000;            // 池U较峰值减 ≥1% → 10%
    uint256 public slippageTier2 = 2000;            // ≥2% → 20%
    uint256 public slippageTier3 = 4000;            // ≥3% → 40%
    uint256 public slippageTier4 = 8000;            // ≥4% → 80%
    uint256 public transferSlippage = 1000;         // 转账滑点 10%（转账视同卖出）
    uint256 public poolStage1USDT = 10_000_000e18;  // 阶段1 < 1000 万 U 只卖
    uint256 public poolStage2USDT = 20_000_000e18;  // 阶段2 < 2000 万 U 买额 1:1
    uint256 public snapshotTime = 28860;            // 08:01 北京（秒），keeper cron 对齐
    uint256 public refLevel1Rate = 700;             // 1 代 7%
    uint256 public refLevel2Rate = 200;             // 2-10 代各 2%
    uint256 public refLevel3Rate = 50;              // 11-20 代各 0.5%
    uint256 public refTechnicalRate = 1000;         // 技术运维 10%
    uint256 public refDepth = 20;                   // 推荐最大深度 20 代
    uint256 public swapFeeBps = 25;                 // Pancake V2 交易费 0.25%（getAmountOut 用）
    uint256 public deflationLpRate = 200;           // 每日报销初始 LP 凭证 2%
    uint256 public buyQuotaRate = 10000;            // 买额 = 入金 1:1（阶段 2 用）
    // V9：总供应保险丝。ZYT 仅在建池时由 Creator 铸出一次（21 亿），此后无任何 mint 路径
    uint256 public totalSupplyCap = 2_100_000_000e18;

    // ---------- 地址 ----------
    address public marketAddress;       // 营销地址（Gnosis Safe 多签）
    address public technicalAddress;    // 技术运维地址（多签）
    address public blackHole;           // 黑洞地址（销毁 + 增量 LP 销毁）
    address public usdt;                // BSC 官方 USDT
    address public factory;             // PancakeSwap V2 Factory（建/查 pair）
    address public pair;                // ZYT/USDT 交易对
    address public zyt;                 // ZYTToken
    address public pool;                // ZYTPoolManager（唯一 swap 通道）
    address public mining;              // ZYTMining（入金/买/卖主入口）
    address public deflation;           // ZYTDeflation
    address public forceSell;           // ZYTForceSell
    address public referral;            // ZYTReferral
    address public creator;             // ZYTLiquidityCreator（初始建池 + LP 锁仓）
    address public keeperAddress;       // 链下 Keeper 触发地址

    bool public paused;

    event Paused(address account);
    event Unpaused(address account);
    event ParamSet(string indexed key, uint256 value);
    event AddressSet(string indexed key, address value);

    constructor() Ownable(msg.sender) {}

    modifier whenNotPaused() {
        require(!paused, "ZYTConfig: paused");
        _;
    }

    function pause() external onlyOwner {
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit Unpaused(msg.sender);
    }

    /** @notice 设置数值参数（多签调用；费率类基点参数强制 ≤ 10000） */
    function setUint(string calldata key, uint256 value) external onlyOwner {
        bytes32 k = keccak256(bytes(key));
        if (k == keccak256("zytMaxSupply")) zytMaxSupply = value;
        else if (k == keccak256("minDeposit")) minDeposit = value;
        else if (k == keccak256("maxDeposit")) maxDeposit = value;
        else if (k == keccak256("marketingRate")) { _requireRate(value); marketingRate = value; }
        else if (k == keccak256("poolRate")) { _requireRate(value); poolRate = value; }
        else if (k == keccak256("powerRate")) { _requireRate(value); powerRate = value; }
        else if (k == keccak256("dailyCompoundRate")) { _requireRate(value); dailyCompoundRate = value; }
        else if (k == keccak256("dynamicQuotaMul")) dynamicQuotaMul = value;
        else if (k == keccak256("staticExitMul")) staticExitMul = value;
        else if (k == keccak256("deflationRate")) { _requireRate(value); deflationRate = value; }
        else if (k == keccak256("deflationFloor")) deflationFloor = value;
        else if (k == keccak256("baseSlippage")) { _requireRate(value); baseSlippage = value; }
        else if (k == keccak256("slippageTier1")) { _requireRate(value); slippageTier1 = value; }
        else if (k == keccak256("slippageTier2")) { _requireRate(value); slippageTier2 = value; }
        else if (k == keccak256("slippageTier3")) { _requireRate(value); slippageTier3 = value; }
        else if (k == keccak256("slippageTier4")) { _requireRate(value); slippageTier4 = value; }
        else if (k == keccak256("transferSlippage")) { _requireRate(value); transferSlippage = value; }
        else if (k == keccak256("poolStage1USDT")) poolStage1USDT = value;
        else if (k == keccak256("poolStage2USDT")) poolStage2USDT = value;
        else if (k == keccak256("snapshotTime")) snapshotTime = value;
        else if (k == keccak256("refLevel1Rate")) { _requireRate(value); refLevel1Rate = value; }
        else if (k == keccak256("refLevel2Rate")) { _requireRate(value); refLevel2Rate = value; }
        else if (k == keccak256("refLevel3Rate")) { _requireRate(value); refLevel3Rate = value; }
        else if (k == keccak256("refTechnicalRate")) { _requireRate(value); refTechnicalRate = value; }
        else if (k == keccak256("refDepth")) refDepth = value;
        else if (k == keccak256("swapFeeBps")) { _requireRate(value); swapFeeBps = value; }
        else if (k == keccak256("deflationLpRate")) { _requireRate(value); deflationLpRate = value; }
        else if (k == keccak256("buyQuotaRate")) { _requireRate(value); buyQuotaRate = value; }
        else if (k == keccak256("totalSupplyCap")) totalSupplyCap = value;
        else revert("ZYTConfig: unknown key");
        emit ParamSet(key, value);
    }

    /// @notice 费率类基点参数统一校验（>10000 会破坏资金分配/滑点计算）
    function _requireRate(uint256 value) private pure {
        require(value <= 10000, "ZYTConfig: rate > 10000");
    }

    /** @notice 设置地址参数（多签调用） */
    function setAddress(string calldata key, address value) external onlyOwner {
        bytes32 k = keccak256(bytes(key));
        if (k == keccak256("marketAddress")) marketAddress = value;
        else if (k == keccak256("technicalAddress")) technicalAddress = value;
        else if (k == keccak256("blackHole")) blackHole = value;
        else if (k == keccak256("usdt")) usdt = value;
        else if (k == keccak256("factory")) factory = value;
        else if (k == keccak256("pair")) pair = value;
        else if (k == keccak256("zyt")) zyt = value;
        else if (k == keccak256("pool")) pool = value;
        else if (k == keccak256("mining")) mining = value;
        else if (k == keccak256("deflation")) deflation = value;
        else if (k == keccak256("forceSell")) forceSell = value;
        else if (k == keccak256("referral")) referral = value;
        else if (k == keccak256("creator")) creator = value;
        else if (k == keccak256("keeperAddress")) keeperAddress = value;
        else revert("ZYTConfig: unknown key");
        emit AddressSet(key, value);
    }

    /** @notice 推荐层级奖励率（1 代 7% / 2-10 代 2% / 11-20 代 0.5%） */
    function refRateForLevel(uint256 level) public view returns (uint256) {
        if (level == 1) return refLevel1Rate;
        if (level <= 10) return refLevel2Rate;
        if (level <= refDepth) return refLevel3Rate;
        return 0;
    }
}

contracts/ZYTDeflation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "./ZYTConfig.sol";
import "./ZYTPoolManager.sol";
import "./ZYTMining.sol";

/**
 * @title ZYTDeflation
 * @notice 每日快照（北京时间 08:01，keeper cron `1 0 * * *` UTC 触发）：
 *         1. 更新快照基准（快照锁定价 + 池 USDT 快照 + 峰值基准刷新）
 *         2. 每日通缩 2%：锁仓合约报销 2% 初始 LP → 抽出 ZYT_a/U_b；
 *            ZYT_a 1% 销毁 + 1% 算力加权分红；U_b 转回 pair + sync（池 U 不变，价格单边上行）
 *         3. 记录当日全网算力（分红分配分母）与当日分红池
 *         通缩至池剩 500 万枚 ZYT 停止（约 299 天，机制自然终止）。
 */
contract ZYTDeflation is Ownable {
    ZYTConfig public config;
    ZYTPoolManager public pool;
    ZYTMining public mining;

    uint256 public lastSnapshotDay;
    uint256 public snapshotCount;

    event DailySnapshot(uint256 day, uint256 burned, uint256 dividend, uint256 snapshotPrice, uint256 snapshotPoolUSDT);
    event DeflationFloorHit(uint256 day);

    constructor(address config_, address pool_, address mining_) Ownable(msg.sender) {
        config = ZYTConfig(config_);
        pool = ZYTPoolManager(pool_);
        mining = ZYTMining(mining_);
    }

    /**
     * @notice 每日快照（北京时间 08:01 触发；仅 Keeper 地址或 owner 可调用，防注入恶意 totalPower）
     * @param totalPower 全网算力和（Keeper 链下统计后传入，避免链上遍历）
     */
    function dailySnapshot(uint256 totalPower) external {
        require(
            msg.sender == config.keeperAddress() || msg.sender == owner(),
            "Deflation: not keeper"
        );
        uint256 day = block.timestamp / 86400;
        require(day > lastSnapshotDay, "Deflation: once per day");
        lastSnapshotDay = day;
        snapshotCount++;

        // 1. 更新快照基准（快照锁定价 / 池 USDT 快照 / 峰值基准）
        pool.updateSnapshot();

        // 2. 每日通缩 2%（真池抽 LP：1% 销毁 + 1% 分红，U 回池 sync），至 500 万枚停止
        uint256 burned = 0;
        uint256 dividend = 0;
        if (pool.poolZYT() > config.deflationFloor()) {
            (burned, dividend) = pool.deflate();
        } else {
            emit DeflationFloorHit(day);
        }

        // 3. 记录全网算力（分红分配分母）与当日分红池
        mining.dailyRelease(day, totalPower);
        mining.recordDailyDividend(day, dividend);

        emit DailySnapshot(day, burned, dividend, pool.getTradePrice(), pool.snapshotPoolUSDT());
    }
}

contracts/ZYTForceSell.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ZYTForceSell
 * @notice 强制卖出规则（防囤积、促流通）。
 *         每个钱包从首次收到币起 60 天内分 4 个 15 天窗口：
 *         0-15 天需卖出持币 20%；15-30 / 30-45 / 45-60 天各需 10%。
 *         到期未卖足 → 差额自动销毁。转账视同卖出，接收方同样启动。
 *         被 ZYTToken 的 _update hook 调用；V8 新增 settleExpired 供 Keeper 定期结算到期义务。
 *         P1-13：settleExpired 以窗口位图去重，同一窗口只结算一次，防 Keeper 重复调用导致递归销毁。
 *         P1-14：checkAndBurn 对跨入未结算窗口的第一笔转账先行结算欠账（堵「拖到期末一笔
 *                转账免费免责」，与 keeper 共用位图）。
 */
contract ZYTForceSell is Ownable {
    uint256 public constant WINDOW = 15 days;
    uint256 public constant TOTAL_WINDOWS = 4;
    // 各窗口最低累计卖出比例（基点）：20% / 10% / 10% / 10%
    uint256 public constant WINDOW1_TARGET = 2000;
    uint256 public constant WINDOW2_TARGET = 1000;
    uint256 public constant WINDOW3_TARGET = 1000;
    uint256 public constant WINDOW4_TARGET = 1000;

    address public token; // ZYTToken 地址（读取余额 + burnFrom）
    address public keeper; // V8：到期结算触发方（Keeper 服务地址，owner 可改）

    mapping(address => uint256) public firstReceiveTime;
    mapping(address => uint256) public soldAmount; // 累计卖出量（转账视同卖出；V9：销毁不扣减）
    mapping(address => bool) public initialized;
    // P1-13：窗口结算位图。bit i 置位表示第 i+1 窗口已由 Keeper 结算过。
    mapping(address => uint256) public settledWindows;

    event FirstReceive(address indexed user, uint256 time);
    event ForceSellBurned(address indexed user, uint256 amount, uint256 window);
    event WindowSettled(address indexed user, uint256 window);

    constructor(address token_) Ownable(msg.sender) {
        token = token_;
    }

    /// @notice 设置 Keeper 结算地址（V8；owner=多签）
    function setKeeper(address _keeper) external onlyOwner {
        keeper = _keeper;
    }

    /// @notice 由 ZYTToken 调用：记录铸币接收方首次收币时间（启动强制卖出窗口）
    function onMint(address to, uint256 amount) external {
        require(msg.sender == token, "ZYTForceSell: only token");
        if (to != address(0) && !initialized[to] && to != address(this)) {
            initialized[to] = true;
            firstReceiveTime[to] = block.timestamp;
            emit FirstReceive(to, block.timestamp);
        }
    }

    /// @notice 由 ZYTToken 调用：记录转账并返回需销毁量
    /// @dev P1-14（AUDIT-5）：过期未结算窗口的欠账在转账路径上先行结算。
    ///      修前 soldAmount += amount 先于欠账判定，本次转账自身即充当卖出进度，
    ///      用户可把全部义务拖到最后一期用一笔转账免费完成（实测窗口 4 转 50% 零销毁免责）。
    ///      修后：当前窗口若尚未被结算（keeper 的 settleExpired 或本函数），先按
    ///      「转账前」的 soldAmount 判定欠账并烧毁（上限为本次转账量），再照常累加
    ///      本次卖出进度。与 settleExpired 共用 settledWindows 位图（P1-13），
    ///      谁先结算谁置位，互不重复；每期足额卖出的正常用户不受任何影响。
    function checkAndBurn(address from, address to, uint256 amount) external returns (uint256) {
        require(msg.sender == token, "ZYTForceSell: only token");
        uint256 burned = 0;

        // 首次收币（from 为铸币地址时由 to 触发，转账时由 from 触发）
        if (to != address(0) && !initialized[to] && to != address(this)) {
            initialized[to] = true;
            firstReceiveTime[to] = block.timestamp;
            emit FirstReceive(to, block.timestamp);
        }
        if (!initialized[from] && from != address(0)) {
            initialized[from] = true;
            firstReceiveTime[from] = block.timestamp;
            emit FirstReceive(from, block.timestamp);
        }

        // P1-14：跨入未结算窗口的第一笔转账 → 先结算此前各期累计欠账。
        // 判定基准用「转账前」的 soldAmount（不把本次算进去），堵死「拖到期末一笔转账免费免责」。
        uint256 elapsed = block.timestamp - firstReceiveTime[from];
        if (elapsed >= WINDOW) {
            uint256 win = _currentWindow(elapsed);
            uint256 bit = 1 << (win - 1);
            if ((settledWindows[from] & bit) == 0) {
                settledWindows[from] |= bit;
                uint256 targetBps = _targetBps(elapsed);
                // P1-9 口径：以「转账前余额（持币总量）」为基数（本函数在 super._update 之后调用）
                uint256 bal = IERC20View(token).balanceOf(from) + amount;
                uint256 required = bal * targetBps / 10000;
                if (soldAmount[from] < required) {
                    uint256 deficit = required - soldAmount[from];
                    burned = amount < deficit ? amount : deficit;
                    emit ForceSellBurned(from, burned, win);
                }
                emit WindowSettled(from, win);
            }
        }

        // 转账视同卖出：本次量照常计入累计进度（供后续窗口判定使用）
        soldAmount[from] += amount;

        return burned;
    }

    /**
     * @notice V8：到期自动销毁结算（Keeper 或 owner 调用）
     * @dev 对指定用户检查当前窗口累计应卖量，未卖足部分销毁差额（上限为持币余额）
     * @return burned 本次销毁数量
     */
    function settleExpired(address user) external returns (uint256 burned) {
        require(msg.sender == keeper || msg.sender == owner(), "FS: not keeper");
        require(initialized[user], "FS: not init");
        uint256 elapsed = block.timestamp - firstReceiveTime[user];
        if (elapsed < WINDOW) return 0; // 未到期

        uint256 win = _currentWindow(elapsed);
        uint256 bit = 1 << (win - 1);
        // P1-13 修复：同一窗口只结算一次。
        // 原实现每次调用都按「当前余额 × 目标比例」重算 required，而 V9 规定销毁不扣减 soldAmount，
        // 于是余额下降使下次 required 同步下降，形成递归衰减：余额 1000 在 20% 窗口被连续调用四次
        // 会依次销毁 200 / 160 / 128 / 102.4，四天蚀掉约 59%。Keeper 一旦定期调用就是持续抽水。
        if ((settledWindows[user] & bit) != 0) return 0;
        settledWindows[user] |= bit;

        uint256 targetBps = _targetBps(elapsed);
        uint256 bal = IERC20View(token).balanceOf(user);
        uint256 required = bal * targetBps / 10000;
        if (soldAmount[user] < required) {
            uint256 deficit = required - soldAmount[user];
            burned = deficit < bal ? deficit : bal;
            if (burned > 0) {
                IERC20Burnable(token).burnFrom(user, burned); // forceSell 为授权 burner
                emit ForceSellBurned(user, burned, win);
            }
        }
        emit WindowSettled(user, win);
    }

    /// @notice 当前累计应卖目标（基点）：15d=20%、30d=30%、45d=40%、60d+=50%
    /// @dev 口径（2026-09-22 用户确认）：每期最低卖出比例为 20% / 10% / 10% / 10%，
    ///      逐期累计即 20% / 30% / 40% / 50%。常量加总 = 5000，与累计口径一致。
    ///      （原注释误写 60%，与常量加总不符，此处已更正）
    function _targetBps(uint256 elapsed) internal pure returns (uint256) {
        if (elapsed >= 4 * WINDOW) return WINDOW1_TARGET + WINDOW2_TARGET + WINDOW3_TARGET + WINDOW4_TARGET; // 50%
        if (elapsed >= 3 * WINDOW) return WINDOW1_TARGET + WINDOW2_TARGET + WINDOW3_TARGET;           // 40%
        if (elapsed >= 2 * WINDOW) return WINDOW1_TARGET + WINDOW2_TARGET;                           // 30%
        return WINDOW1_TARGET;                                                                      // 20%
    }

    function _currentWindow(uint256 elapsed) internal pure returns (uint256) {
        if (elapsed >= 4 * WINDOW) return 4;
        if (elapsed >= 3 * WINDOW) return 3;
        if (elapsed >= 2 * WINDOW) return 2;
        return 1;
    }
}

interface IERC20View {
    function balanceOf(address account) external view returns (uint256);
}

interface IERC20Burnable {
    function burnFrom(address from, uint256 amount) external;
}

contracts/ZYTLiquidityCreator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/UniV2.sol";

/**
 * @title ZYTLiquidityCreator（初始建池 + LP 持有 + 通缩执行）
 * @notice v9 双重身份：
 *         1. 初始建池：铸造 21 亿 ZYT（一次性的全量供应）+ 收取 2.1 万 USDT，
 *            直接创建 ZYT/USDT 真实 pair 并注入，LP 凭证由本合约持有
 *         2. 通缩执行器：每日被 PoolManager 调用 skimDeflation，报销 2% LP
 *            （removeLiquidity）并把抽出的 ZYT/USDT 转交 Pool 处理（U 回池 sync）
 *         安全设计：
 *         - 常态出口 = skimDeflation（仅 Pool 可调，按剩余凭证 2% 递减，约 299 天自然耗尽）
 *         - owner 出口 = withdrawLp（多签可提取，对应「不锁仓」运营口径）
 *           ⚠️ 提取会同步减少 skimDeflation 的可用 LP 基数，提空则通缩停摆
 *         - 本合约须加入 ZYTToken 白名单（系统路径豁免）
 */
contract ZYTLiquidityCreator is Ownable, ReentrancyGuard {
    address public immutable zyt;
    address public immutable usdt;
    address public immutable factory;
    address public immutable blackHole;
    address public pair;                // ZYT/USDT 交易对（建池后固化）
    address public poolManager;         // ZYTPoolManager（唯一 skimDeflation 调用方）

    // 本合约当前持有的 LP 凭证量。恒等于 IERC20(pair).balanceOf(address(this))，
    // 由 createInitialPool / skimDeflation / withdrawLp 三处同步维护。
    uint256 public lockedLiquidity;
    uint256 public totalZytSeeded;
    uint256 public totalUsdtSeeded;
    uint256 public totalDeflationZytOut;
    uint256 public totalDeflationUsdtOut;
    uint256 public totalLpWithdrawn;    // 累计由 owner 提取的 LP 量

    bool public initialized;

    event InitialPoolCreated(address indexed pair, uint256 zytIn, uint256 usdtIn, uint256 liquidity);
    event PoolManagerChanged(address indexed poolManager);
    event DeflationSkimmed(uint256 lpBurned, uint256 zytAmt, uint256 usdtAmt);
    event LpWithdrawn(address indexed to, uint256 amount);

    constructor(
        address zyt_,
        address usdt_,
        address factory_,
        address blackHole_
    ) Ownable(msg.sender) {
        require(
            zyt_ != address(0) && usdt_ != address(0) &&
            factory_ != address(0) && blackHole_ != address(0),
            "Creator: zero addr"
        );
        zyt = zyt_;
        usdt = usdt_;
        factory = factory_;
        blackHole = blackHole_;
    }

    function setPoolManager(address _pool) external onlyOwner {
        require(_pool != address(0), "Creator: zero addr");
        poolManager = _pool;
        emit PoolManagerChanged(_pool);
    }

    /**
     * @notice 初始建池（部署时手动调用一次）：
     *         铸出全量 ZYT（21 亿）+ 收取初始 USDT（2.1 万）→ 创建/获取 pair →
     *         两侧注入 → LP 由本合约持有（owner 可提取；常态用于每日 2% 递减式通缩报销）
     * @param zytAmount 全量 ZYT（21 亿枚）
     * @param usdtAmount 初始 USDT（2.1 万枚；调用方需先 approve）
     * @return pairAddr 交易对地址
     */
    function createInitialPool(uint256 zytAmount, uint256 usdtAmount)
        external
        onlyOwner
        nonReentrant
        returns (address pairAddr)
    {
        require(!initialized, "Creator: initialized");
        require(zytAmount > 0 && usdtAmount > 0, "Creator: zero amount");

        // 1. 全量铸造 ZYT 到本合约（此后无任何 mint 路径，总供应恒减）
        IZYTTokenMint(zyt).mintTo(address(this), zytAmount);

        // 2. 创建或获取 pair
        pairAddr = IUniswapV2Factory(factory).getPair(zyt, usdt);
        if (pairAddr == address(0)) {
            pairAddr = IUniswapV2Factory(factory).createPair(zyt, usdt);
        }
        pair = pairAddr;
        initialized = true;

        // 3. 两侧注入
        IERC20(usdt).transferFrom(msg.sender, address(this), usdtAmount);
        IERC20(zyt).transfer(pairAddr, zytAmount);
        IERC20(usdt).transfer(pairAddr, usdtAmount);

        // 4. LP 铸给本合约，永久锁仓
        uint256 liquidity = IUniswapV2Pair(pairAddr).mint(address(this));
        lockedLiquidity = liquidity;
        totalZytSeeded = zytAmount;
        totalUsdtSeeded = usdtAmount;

        emit InitialPoolCreated(pairAddr, zytAmount, usdtAmount, liquidity);
    }

    /**
     * @notice 每日通缩报销（仅 ZYTPoolManager 调用；Pool 侧处于 swapGate 期间）
     * @dev 报销 rateBps 基点的锁仓 LP → removeLiquidity → 两侧资产转交 Pool。
     *      Pool 把 U 直接转回 pair + sync（净效果只减池内 ZYT），ZYT 按 1% 烧 + 1% 分红处理。
     *      AUDIT-1：LP 耗尽（withdrawLp 提空或自然衰减至 1 wei 以下）时返回 (0,0)
     *      而非 revert——否则 dailySnapshot 整笔回滚，快照价/分红/全网算力记录全部停摆。
     * @return zytAmt 抽出的 ZYT 数量
     * @return usdtAmt 抽出的 USDT 数量
     */
    function skimDeflation(uint256 rateBps)
        external
        nonReentrant
        returns (uint256 zytAmt, uint256 usdtAmt)
    {
        require(msg.sender == poolManager, "Creator: not pool");
        require(rateBps > 0 && rateBps <= 200, "Creator: bad rate");
        uint256 lpBal = IERC20(pair).balanceOf(address(this));
        uint256 burnAmt = lpBal * rateBps / 10000;
        // AUDIT-1：LP 不足以报销最小单位（提空或极端衰减）→ 静默返回。
        // 通缩停摆但 dailySnapshot 链继续（updateSnapshot/dailyRelease/recordDailyDividend 正常执行）。
        if (burnAmt == 0) return (0, 0);

        // V2 burn：先把 LP 转回 pair，再按比例取回两侧资产
        IERC20(pair).transfer(pair, burnAmt);
        (uint256 a0, uint256 a1) = IUniswapV2Pair(pair).burn(address(this));
        lockedLiquidity -= burnAmt;

        // 按 pair 内排序归位（ZYT/USDT）
        if (IUniswapV2Pair(pair).token0() == zyt) {
            zytAmt = a0;
            usdtAmt = a1;
        } else {
            zytAmt = a1;
            usdtAmt = a0;
        }

        // 转交 Pool 处理（U 回池 sync、ZYT 烧/分红）
        if (zytAmt > 0) {
            IERC20(zyt).transfer(msg.sender, zytAmt);
            totalDeflationZytOut += zytAmt;
        }
        if (usdtAmt > 0) {
            IERC20(usdt).transfer(msg.sender, usdtAmt);
            totalDeflationUsdtOut += usdtAmt;
        }

        emit DeflationSkimmed(burnAmt, zytAmt, usdtAmt);
    }

    /**
     * @notice owner 提取 LP 凭证（对应「不锁仓」运营口径）
     * @dev 提取后 lockedLiquidity 同步递减，skimDeflation 的可用基数随之减少。
     *      提空则 skimDeflation 的 require(burnAmt > 0) 失败，每日通缩停摆，属预期行为。
     *      上线后 owner 归 W2 治理多签，单方无法提取。
     * @param to 接收地址
     * @param amount 提取的 LP 数量
     */
    function withdrawLp(address to, uint256 amount) external onlyOwner nonReentrant {
        require(to != address(0), "Creator: zero addr");
        require(amount > 0, "Creator: zero amount");
        uint256 bal = IERC20(pair).balanceOf(address(this));
        require(amount <= bal, "Creator: insufficient lp");
        // 用「实际余额 − 提取量」重算，避免历史不同步导致下溢
        lockedLiquidity = bal - amount;
        totalLpWithdrawn += amount;
        require(IERC20(pair).transfer(to, amount), "Creator: lp out");
        emit LpWithdrawn(to, amount);
    }

    /// @notice 合约当前持有的 LP 读数（前端展示；语义为「持有量」，不再代表「已锁定」）
    function lockedLpOf(address) external view returns (uint256) {
        return lockedLiquidity;
    }
}

interface IZYTTokenMint {
    function mintTo(address to, uint256 amount) external;
}

contracts/ZYTMining.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./ZYTConfig.sol";
import "./ZYTPoolManager.sol";
import "./ZYTReferral.sol";
import "./ZYTCompute.sol";
import "./interfaces/IZYTTokenLike.sol";

/**
 * @title ZYTMining
 * @notice v9 入金/买入/卖出主入口。
 *         - 入金（仅 USDT，100-500U 可调）：40% 生态 USDT 直发（30% 代数 + 10% 技术），
 *           60% 由 PoolManager 真实组 LP 凭证销毁；入金者获算力（日复利 1%）与买额（1:1）
 *         - 买入：真实 AMM swap（阶段 1 禁买；阶段 2 消耗买额；阶段 3 自由）
 *         - 卖出：真实 AMM swap + 滑点档位 30/30/40；卖出实收 USDT 计入累计提取
 *         - 加速释放（v9 拍板）：静态出局 = 累计提取 ≥ 2×本金（含转出按价计值）；
 *           动态出局 = 动态额度 5×本金被推荐奖励耗尽，复投注入新额度恢复
 *         - 分红：每日通缩 1% + 滑点 30% + 转账税 30%，按日隔离、按算力加权结算（沿用 v8）
 */
contract ZYTMining is ReentrancyGuard {
    ZYTConfig public config;
    ZYTPoolManager public pool;
    ZYTReferral public referral;
    address public zytToken;
    address public usdt;
    address public deflation;

    struct UserState {
        uint256 depositTotal;       // 累计入金 USDT
        uint256 withdrawTotal;      // 累计提取 USDT（静态 2 倍判断）
        uint256 powerBase;          // 算力基数（累计，不随时间变化）
        uint256 powerDay;           // v16：首次入金日（分红起算下限；复利基准已改为全网 launchDay）
        uint256 pendingDividend;    // 待提取分红（ZYT）
        bool isExited;              // 静态出局标记（复投时重置）
        uint256 receivedValue;      // 累计受赠 USDT 等值（转账接收折算）
        uint256 exitDay;            // 静态出局日（算力停发起点，保留 base 供分红回算）
        // ---- v9 新增 ----
        uint256 buyQuota;           // 买额累计（= 入金 1:1）
        uint256 buyUsed;            // 已用买额
        uint256 dynamicQuota;       // 动态额度总量（= 入金 × 5）
        uint256 dynamicWithdrawn;   // 已消耗（推荐奖励 USDT 逐笔扣减）
        bool dynamicExited;         // 动态出局标记（额度耗尽；复投解除）
    }

    struct DailyInfo {
        uint256 totalPower;         // 当日全网算力和（Keeper 传入）
        uint256 dividendAmount;     // 当日分红总额（ZYT）
    }

    mapping(address => UserState) public users;
    mapping(uint256 => DailyInfo) public dailyInfo;
    mapping(address => uint256) public dividendClaimedDay; // 按日结算游标
    uint256 public constant MAX_SETTLE_DAYS = 365;
    uint64 public launchDay;                    // v16：全网算力复利基准日（首次入金日，0=未启动）

    event Deposited(address indexed user, uint256 usdt, uint256 power, uint256 quota, address ref);
    event Bought(address indexed user, uint256 usdtIn, uint256 zytOut);
    event Sold(address indexed user, uint256 zytIn, uint256 usdtOut, uint256 rate);
    event StaticExited(address indexed user);
    event DynamicExited(address indexed user);
    event DailyReleased(uint256 day, uint256 totalPower);
    event DividendSettled(address indexed user, uint256 amount, uint256 fromDay, uint256 toDay);
    event Claimed(address indexed user, uint256 amount);
    event TransferLedger(address indexed user, uint256 zytAmount, uint256 usdtValue, bool isOut);
    event RefPaid(address indexed receiver, uint256 usdtAmount, uint256 level);

    modifier whenNotPaused() {
        require(!config.paused(), "Mining: paused");
        _;
    }

    modifier onlyDeflation() {
        require(msg.sender == deflation, "Mining: only deflation");
        _;
    }

    constructor(
        address config_,
        address pool_,
        address referral_,
        address zytToken_,
        address usdt_
    ) {
        config = ZYTConfig(config_);
        pool = ZYTPoolManager(pool_);
        referral = ZYTReferral(referral_);
        zytToken = zytToken_;
        usdt = usdt_;
    }

    function setDeflation(address _deflation) external {
        require(msg.sender == config.owner(), "Mining: not owner");
        deflation = _deflation;
    }

    /**
     * @notice 入金（仅 USDT，最小 100U / 单笔上限 500U，可调）
     * @dev v9 资金流：40% USDT 直发（30% 代数 + 10% 技术，含动态额度消耗）
     *      60% 转 PoolManager 真实组 LP 凭证销毁；入金者获算力 + 买额（1:1）+ 动态额度（×5）
     */
    function deposit(uint256 usdtAmount, address ref) external nonReentrant whenNotPaused {
        require(usdtAmount >= config.minDeposit() && usdtAmount <= config.maxDeposit(), "Mining: amount range");
        IERC20(usdt).transferFrom(msg.sender, address(this), usdtAmount);

        // 1. 推荐关系绑定（先绑定再分账）
        referral.bind(msg.sender, ref);

        // 2. 40% 生态奖励：30% 代数（逐笔消耗推荐人动态额度）+ 10% 技术运维
        _distributeRef(msg.sender, usdtAmount);

        // 3. 60% 注入流动性池并销毁（真池 halfBuy + addLiquidity + LP 凭证黑洞）
        uint256 poolIn = usdtAmount * config.poolRate() / 10000;
        IERC20(usdt).transfer(address(pool), poolIn);
        pool.injectLiquidity(poolIn);

        // 4. 用户记账：算力（复利固化后重置，P1-12）+ 买额 + 动态额度
        UserState storage u = users[msg.sender];
        uint256 today = block.timestamp / 86400;
        _settleDividend(msg.sender, today, true);
        u.isExited = false;
        u.dynamicExited = false;
        u.depositTotal += usdtAmount;
        // v16 算力补偿：launchDay = 全网首次入金日；个人算力统一按 launchDay 基准复利，
        // 后入金者入金即按 1.01^(today-launchDay) 补偿（先入有先机，后入有算力补偿）
        if (launchDay == 0) launchDay = uint64(today);
        if (u.powerDay == 0) u.powerDay = today; // 分红起算日（仅首次入金写入）
        uint256 power = usdtAmount * config.powerRate() / 10000;
        // v16：powerBase 只存算力基数累计，复利统一在 _powerOf 按 launchDay 计算，
        // 不再逐用户固化（原 P1-12 复投重置逻辑随统一基准自然取消）
        u.exitDay = 0;
        u.powerBase += power;
        u.buyQuota += usdtAmount * config.buyQuotaRate() / 10000;
        u.dynamicQuota += usdtAmount * config.dynamicQuotaMul();

        emit Deposited(msg.sender, usdtAmount, power, u.buyQuota, ref);
    }

    /**
     * @notice 买入 ZYT（真实 AMM swap）
     * @dev 阶段 1 禁买；阶段 2 消耗买额（入金 1:1）；阶段 3 自由。
     *      USDT 直达 PoolManager，ZYT 从 pair 直达用户（gate 放行）。
     */
    function buy(uint256 usdtIn) external nonReentrant whenNotPaused returns (uint256 zytOut) {
        require(usdtIn > 0, "Mining: zero");
        uint256 stage = pool.getStage();
        require(stage != 1, "Mining: buy disabled in stage1");
        UserState storage u = users[msg.sender];
        if (stage == 2) {
            require(u.buyQuota - u.buyUsed >= usdtIn, "Mining: over buy quota");
            u.buyUsed += usdtIn;
        }
        IERC20(usdt).transferFrom(msg.sender, address(pool), usdtIn);
        zytOut = pool.buyFor(msg.sender, usdtIn);
        emit Bought(msg.sender, usdtIn, zytOut);
    }

    /**
     * @notice 卖出 ZYT 换 USDT（真实 AMM swap + 滑点档位 30/30/40）
     * @dev 卖出实收 USDT 计入累计提取；累计提取 ≥ 2×本金 + 受赠 → 静态出局
     */
    function sellZyt(uint256 zytGross) external nonReentrant whenNotPaused {
        uint256 rate = pool.getCurrentSlippage();
        uint256 usdtOut = pool.sellFor(msg.sender, zytGross);
        IZYTTokenLike(zytToken).recordSellUsdt(msg.sender, usdtOut);
        UserState storage u = users[msg.sender];
        u.withdrawTotal += usdtOut;
        if (!u.isExited && ZYTCompute.isStaticExited(u.withdrawTotal, u.depositTotal, config.staticExitMul(), u.receivedValue)) {
            _markExited(msg.sender, u);
        }
        emit Sold(msg.sender, zytGross, usdtOut, rate);
    }

    // ---------- P1-7 转账折算记账（仅 ZYTToken 调用） ----------

    /// @notice 转出折算：按快照价计入累计提取（转账视同卖出，堵静态 2 倍绕过）
    function recordTransferOut(address user, uint256 zytAmount) external {
        require(msg.sender == zytToken, "Mining: not token");
        if (zytAmount == 0) return;
        uint256 price = pool.getTradePrice();
        if (price == 0) return;
        uint256 usdtValue = zytAmount * price / 1e18;
        if (usdtValue == 0) return;

        UserState storage u = users[user];
        u.withdrawTotal += usdtValue;
        if (!u.isExited && ZYTCompute.isStaticExited(u.withdrawTotal, u.depositTotal, config.staticExitMul(), u.receivedValue)) {
            _markExited(user, u);
        }
        emit TransferLedger(user, zytAmount, usdtValue, true);
    }

    /// @notice 转入折算：计入受赠额（等额提高接收方提取上限，额度守恒）
    function recordTransferIn(address user, uint256 zytAmount) external {
        require(msg.sender == zytToken, "Mining: not token");
        if (zytAmount == 0) return;
        uint256 price = pool.getTradePrice();
        if (price == 0) return;
        uint256 usdtValue = zytAmount * price / 1e18;
        if (usdtValue == 0) return;
        users[user].receivedValue += usdtValue;
        emit TransferLedger(user, zytAmount, usdtValue, false);
    }

    // ---------- 分红（按日隔离，沿用 v8） ----------

    /// @notice 每日记录全网算力（ZYTDeflation 调用，分红分配分母）
    function dailyRelease(uint256 day, uint256 totalPower) external onlyDeflation {
        dailyInfo[day].totalPower = totalPower;
        emit DailyReleased(day, totalPower);
    }

    /// @notice 登记当日分红总额（ZYTDeflation 调用，通缩 1% 部分）
    function recordDailyDividend(uint256 day, uint256 amount) external onlyDeflation {
        dailyInfo[day].dividendAmount = amount;
    }

    /// @notice 提取分红（三阶段均可；ZYT 从 Pool 分红池转出）
    /// @dev AUDIT-2：零额调用也成功（仅推进游标）。修前 amount == 0 时 revert，
    ///      游标推进被回滚——用户超 365 天无交互后 deposit(strict) 与 claim(零额)
    ///      双向关闭，入金永久阻塞。修后调一次 claim 即可把游标推进一段，
    ///      deposit 的 strict 检查恢复可达。
    function claimDividend() external nonReentrant returns (uint256 amount) {
        uint256 today = block.timestamp / 86400;
        _settleDividend(msg.sender, today, false);
        UserState storage u = users[msg.sender];
        amount = u.pendingDividend;
        if (amount == 0) {
            emit Claimed(msg.sender, 0);   // 游标已推进，无待领分红
            return 0;
        }
        u.pendingDividend = 0;
        pool.payoutDividend(msg.sender, amount);
        emit Claimed(msg.sender, amount);
    }

    function dividendOf(address user) external view returns (uint256 pending, uint256 settledDay) {
        return (users[user].pendingDividend, dividendClaimedDay[user]);
    }

    function _settleDividend(address user, uint256 toDay, bool strict) internal returns (uint256 total) {
        UserState storage u = users[user];
        uint256 from = dividendClaimedDay[user];
        if (from < u.powerDay) from = u.powerDay;
        if (from == 0) {
            dividendClaimedDay[user] = toDay;
            return 0;
        }
        if (from >= toDay) return 0;

        if (strict && toDay - from > MAX_SETTLE_DAYS) {
            revert("Mining: settle dividend first");
        }
        uint256 end = from + MAX_SETTLE_DAYS;
        if (end > toDay) end = toDay;

        for (uint256 d = from; d < end; d++) {
            uint256 divAmt = dailyInfo[d].dividendAmount;
            if (divAmt == 0) continue;
            uint256 dayPower = dailyInfo[d].totalPower;
            if (dayPower == 0) continue;
            uint256 up = _powerOf(user, d);
            if (up == 0) continue;
            total += divAmt * up / dayPower;
        }
        dividendClaimedDay[user] = end;
        if (total > 0) {
            u.pendingDividend += total;
            emit DividendSettled(user, total, from, end);
        }
    }

    // ---------- 出局 ----------

    /// @notice 静态出局：记 exitDay（不清 powerBase，历史分红可回算；day >= exitDay 算力为 0）
    function _markExited(address user, UserState storage u) internal {
        u.isExited = true;
        u.exitDay = block.timestamp / 86400;
        emit StaticExited(user);
    }

    // ---------- 视图 ----------

    function powerOf(address user) public view returns (uint256) {
        return _powerOf(user, block.timestamp / 86400);
    }

    function _powerOf(address user, uint256 day) internal view returns (uint256) {
        UserState storage u = users[user];
        if (u.powerBase == 0) return 0;
        if (u.exitDay > 0 && day >= u.exitDay) return 0;
        // v16：全网统一复利基准 launchDay（首次入金日），个人 powerDay 仅作分红起算
        if (launchDay == 0 || day < uint256(launchDay)) return 0;
        uint256 daysElapsed = day - uint256(launchDay);
        return ZYTCompute.powerWithCompound(u.powerBase, config.dailyCompoundRate(), daysElapsed);
    }

    function userInfo(address user)
        external
        view
        returns (
            uint256 depositTotal,
            uint256 withdrawTotal,
            uint256 power,
            uint256 dynamicQuota,
            uint256 dynamicWithdrawn,
            uint256 buyQuotaLeft,
            bool staticExited,
            bool dynamicExited
        )
    {
        UserState storage u = users[user];
        return (
            u.depositTotal,
            u.withdrawTotal,
            _powerOf(user, block.timestamp / 86400),
            u.dynamicQuota,
            u.dynamicWithdrawn,
            u.buyQuota - u.buyUsed,
            u.isExited,
            u.dynamicExited
        );
    }

    /// @notice P1-7 查询：受赠值与提取上限（= 入金 × 2 + 受赠）
    function transferValueOf(address user) external view returns (uint256 receivedValue, uint256 withdrawCap) {
        UserState storage u = users[user];
        receivedValue = u.receivedValue;
        withdrawCap = u.depositTotal * config.staticExitMul() + receivedValue;
    }

    // ---------- 40% 生态奖励（USDT 直发 + 动态额度消耗） ----------

    /**
     * @notice 40% 生态奖励分发：30% 按代数给推荐链（逐笔消耗推荐人动态额度）、10% 技术
     * @dev 直推数 = 可拿代数（决策 21）；推荐人动态额度耗尽部分转营销账户（加速释放口径）；
     *      代际拿不满的余额转营销账户。
     */
    function _distributeRef(address user, uint256 usdtAmount) internal {
        address[] memory ancestors = referral.getAncestors(user, config.refDepth());

        // 技术运维与社区建设 10%
        uint256 techUsdt = usdtAmount * config.refTechnicalRate() / 10000;
        if (techUsdt > 0 && config.technicalAddress() != address(0)) {
            IERC20(usdt).transfer(config.technicalAddress(), techUsdt);
        }

        // 代数奖励预算 = 40% − 10% = 30%
        uint256 refBudget = usdtAmount * (config.marketingRate() - config.refTechnicalRate()) / 10000;
        uint256 paid = 0;

        for (uint256 i = 0; i < ancestors.length; i++) {
            address a = ancestors[i];
            if (a == address(0)) break;
            // 直推数 = 可拿代数：上级直推人数不足层级则跳过
            if (referral.downlineCount(a) < i + 1) continue;
            uint256 rate = config.refRateForLevel(i + 1);
            if (rate == 0) continue;
            uint256 rewardUsdt = usdtAmount * rate / 10000;
            if (paid + rewardUsdt > refBudget) {
                rewardUsdt = refBudget - paid;
            }
            if (rewardUsdt == 0) break;
            // v9 加速释放：推荐奖励逐笔消耗推荐人动态额度，耗尽即动态出局
            uint256 paidOut = _consumeQuota(a, rewardUsdt);
            if (paidOut == 0) continue;
            IERC20(usdt).transfer(a, paidOut);
            paid += paidOut;
            emit RefPaid(a, paidOut, i + 1);
        }

        // 拿不满的余额转营销账户
        if (paid < refBudget && config.marketAddress() != address(0)) {
            IERC20(usdt).transfer(config.marketAddress(), refBudget - paid);
        }
    }

    /// @notice 消耗推荐人动态额度（加速释放），返回实发量；耗尽触发动态出局
    function _consumeQuota(address referrer, uint256 want) internal returns (uint256 paid) {
        UserState storage u = users[referrer];
        if (u.dynamicQuota == 0 || u.dynamicWithdrawn >= u.dynamicQuota) return 0;
        uint256 left = u.dynamicQuota - u.dynamicWithdrawn;
        paid = want < left ? want : left;
        u.dynamicWithdrawn += paid;
        if (!u.dynamicExited && u.dynamicWithdrawn >= u.dynamicQuota) {
            u.dynamicExited = true;
            emit DynamicExited(referrer);
        }
    }
}

contracts/ZYTPoolManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./ZYTConfig.sol";
import "./interfaces/UniV2.sol";

/**
 * @title ZYTPoolManager
 * @notice v9 底池管理：真实 PancakeSwap V2 ZYT/USDT pair 为唯一底池，
 *         本合约是唯一交易通道（gate 模式，ZYTToken 强制校验）。
 *         - 入金 60%：一半 USDT 换 ZYT（真实 swap），另一半与换得 ZYT 按最优比例组 LP，
 *           LP 凭证全额转黑洞销毁（NBDAO buyAndAddLP 模式的真池实现）
 *         - 买入：USDT → pair.swap → ZYT 直达用户（阶段 1 禁买；阶段 2 由 Mining 校验买额）
 *         - 卖出：ZYT 滑点档位（30% 营销 / 30% 分红池 / 40% 销毁）→ 净额 swap → USDT 给用户
 *         - 滑点档位基准（v9 拍板）：max(初始池U, 历史峰值池U)；当前池 U 较基准减 1/2/3/4% → 10/20/40/80%
 *         - 每日通缩：锁仓合约报销 2% 初始 LP → 抽出 ZYT_a/U_b；ZYT_a 1% 烧 + 1% 分红，
 *           U_b 直接转回 pair 并 sync（净效果只减池内 ZYT，池 U 不变，价格单边上行）
 *         - swapGate：swap 前置位/后清位，ZYTToken 据此放行「流出 pair」路径
 */
contract ZYTPoolManager is Ownable, ReentrancyGuard {
    ZYTConfig public config;
    address public zytToken;
    address public usdt;
    address public pair;        // ZYT/USDT 交易对
    address public locker;      // 锁仓合约（= ZYTLiquidityCreator，持初始 LP）
    address public mining;      // ZYTMining（入金/买/卖主入口）
    address public deflation;   // ZYTDeflation

    bool public swapGate;       // 交易闸门（ZYTToken 流出 pair 路径校验）
    bool public zytIsToken0;    // pair 内排序标记

    // ---------- 快照与基准 ----------
    uint256 public snapshotPrice;       // 每日 08:01 快照锁定价（记账：转账计值/强卖/额度）
    uint256 public snapshotPoolUSDT;    // 每日快照的池 USDT（统计）
    uint256 public lastSnapshotAt;
    uint256 public peakPoolUSDT;        // 历史峰值池 USDT（滑点档位基准，max(初始, 峰值)）
    uint256 public totalLpBurned;       // 累计销毁 LP（入金 60% 凭证）

    uint256 public dividendPoolZyt;     // 分红池（ZYT）：通缩 1% + 卖币滑点 30% + 转账税 30%
    uint256 public reserveUSDT;         // 自持 USDT（组 LP 残留，兑付兜底储备）

    event LiquidityInjected(address indexed user, uint256 usdtIn, uint256 lpBurned);
    event Bought(address indexed user, uint256 usdtIn, uint256 zytOut);
    event Sold(address indexed seller, uint256 zytGross, uint256 slip, uint256 usdtOut);
    event SnapshotUpdated(uint256 price, uint256 poolUSDT, uint256 time);
    event Deflated(uint256 burned, uint256 dividend, uint256 usdtResynced);
    event SlippageCollected(uint256 rate, uint256 toMarket, uint256 toDividend, uint256 toBurn);
    event DividendAccrued(uint256 amount);

    modifier onlyMining() {
        require(msg.sender == mining, "Pool: only mining");
        _;
    }

    modifier onlyDeflation() {
        require(msg.sender == deflation, "Pool: only deflation");
        _;
    }

    modifier gated() {
        swapGate = true;
        _;
        swapGate = false;
    }

    constructor(address config_, address zytToken_, address usdt_) Ownable(msg.sender) {
        config = ZYTConfig(config_);
        zytToken = zytToken_;
        usdt = usdt_;
    }

    function setPair(address _pair) external onlyOwner {
        require(_pair != address(0), "Pool: zero pair");
        pair = _pair;
        zytIsToken0 = IUniswapV2Pair(_pair).token0() == zytToken;
        // 初始峰值 = 建池后的池 USDT（2.1 万）
        (, uint256 uRes) = _reserves();
        if (peakPoolUSDT < uRes) peakPoolUSDT = uRes;
    }

    function setLocker(address _locker) external onlyOwner {
        locker = _locker;
    }

    function setMining(address _mining) external onlyOwner {
        mining = _mining;
    }

    function setDeflation(address _deflation) external onlyOwner {
        deflation = _deflation;
    }

    // ---------- 视图 ----------

    /// @notice pair 储备（zytReserve, usdtReserve）
    function _reserves() internal view returns (uint256 zRes, uint256 uRes) {
        (uint112 r0, uint112 r1, ) = IUniswapV2Pair(pair).getReserves();
        if (zytIsToken0) {
            return (uint256(r0), uint256(r1));
        }
        return (uint256(r1), uint256(r0));
    }

    function getReservesPublic() external view returns (uint256 zytReserve, uint256 usdtReserve) {
        return _reserves();
    }

    function poolZYT() external view returns (uint256) {
        (uint256 zRes, ) = _reserves();
        return zRes;
    }

    function poolUSDT() external view returns (uint256) {
        (, uint256 uRes) = _reserves();
        return uRes;
    }

    /// @notice 实时价（U per ZYT，1e18 精度）
    function getPrice() public view returns (uint256) {
        (uint256 zRes, uint256 uRes) = _reserves();
        if (zRes == 0) return 0;
        return uRes * 1e18 / zRes;
    }

    /// @notice 记账价（当日 08:01 快照锁定价；转账计值/强卖/额度折算统一用）
    function getTradePrice() external view returns (uint256) {
        if (snapshotPrice == 0) return getPrice();
        return snapshotPrice;
    }

    /// @notice 阶段门控：1 只卖不买 / 2 买额 1:1 / 3 自由（度量 = 池 USDT 余额）
    function getStage() public view returns (uint256) {
        (, uint256 uRes) = _reserves();
        if (uRes < config.poolStage1USDT()) return 1;
        if (uRes < config.poolStage2USDT()) return 2;
        return 3;
    }

    /// @notice 当前滑点档位（基点）：池 USDT 较峰值基准的减少比例分档
    function getCurrentSlippage() public view returns (uint256) {
        (, uint256 uRes) = _reserves();
        if (peakPoolUSDT == 0 || uRes >= peakPoolUSDT) return config.baseSlippage();
        uint256 reduction = (peakPoolUSDT - uRes) * 10000 / peakPoolUSDT;
        if (reduction >= 400) return config.slippageTier4();   // 80%
        if (reduction >= 300) return config.slippageTier3();   // 40%
        if (reduction >= 200) return config.slippageTier2();   // 20%
        if (reduction >= 100) return config.slippageTier1();   // 10%
        return config.baseSlippage();                          // 5%
    }

    // ---------- 入金 60% 处置 ----------

    /**
     * @notice 入金 60% 注入流动性：一半真实 swap 买 ZYT，另一半与 ZYT 按最优比例组 LP，
     *         LP 凭证全额转黑洞销毁。仅 ZYTMining 调用（Mining 已完成 40% 直发与校验）。
     */
    function injectLiquidity(uint256 usdtIn) external onlyMining nonReentrant gated returns (uint256 lpBurned) {
        require(pair != address(0) && locker != address(0), "Pool: pair/locker unset");
        require(usdtIn > 0, "Pool: zero");
        uint256 half = usdtIn / 2;
        require(half > 0, "Pool: too small");

        // 1. 一半 USDT 真实换 ZYT（swap 输出到本合约）
        uint256 zytC = _swapUsdtForZyt(half, address(this));

        // 2. 另一半 USDT 与 ZYT 按最优比例组 LP（V2 公式，不经 Router）
        uint256 usdtLeft = usdtIn - half;
        uint256 lp;
        uint256 zytUsed;
        (lp, zytUsed) = _addLiquidity(usdtLeft, zytC, address(this));

        // 3. 组 LP 未用尽的 ZYT 残留转入分红池（防止账面漂移）
        uint256 residue = zytC - zytUsed;
        if (residue > 0) {
            dividendPoolZyt += residue;
            emit DividendAccrued(residue);
        }

        // 4. LP 凭证销毁（「60% 注入流动性池并销毁」的落实）
        lpBurned = lp;
        if (lp > 0) {
            IERC20(pair).transfer(config.blackHole(), lp);
            totalLpBurned += lp;
        }
        emit LiquidityInjected(msg.sender, usdtIn, lp);
    }

    // ---------- 买入 / 卖出 ----------

    /**
     * @notice 买入：USDT → pair → ZYT 直达用户。仅 ZYTMining 调用（阶段与买额在 Mining 校验）。
     * @dev USDT 须已由 Mining 转入本合约。
     */
    function buyFor(address user, uint256 usdtIn) external onlyMining nonReentrant gated returns (uint256 zytOut) {
        require(getStage() != 1, "Pool: buy disabled in stage1");
        require(user != address(0) && usdtIn > 0, "Pool: zero");
        // 先读储备再转币（getAmountOut 的 reserveIn 必须不含 amountIn，peak 不得双重计入）
        (uint256 zRes, uint256 uResBefore) = _reserves();
        IERC20(usdt).transfer(pair, usdtIn);
        zytOut = UniV2Lib.getAmountOut(usdtIn, uResBefore, zRes, config.swapFeeBps());
        require(zytOut > 0, "Pool: zero out");
        _pairSwap(0, zytOut, user);
        _updatePeak(uResBefore + usdtIn);
        emit Bought(user, usdtIn, zytOut);
    }

    /**
     * @notice 卖出：ZYT 滑点分配后净额换 USDT。仅 ZYTMining 调用。
     * @dev ZYT 须已由本合约 transferFrom 用户（卖闸：msg.sender = pool）。
     * @return usdtOut 净 USDT 输出（滑点后）
     */
    function sellFor(address user, uint256 zytGross) external onlyMining nonReentrant gated returns (uint256 usdtOut) {
        require(zytGross > 0, "Pool: zero");
        (uint256 zRes, uint256 uRes) = _reserves();

        // 0. 从用户拉入 ZYT（msg.sender = pool，卖闸放行；to = pool 白名单 → 记账/强卖/统计在 Token 层完成）
        IERC20(zytToken).transferFrom(user, address(this), zytGross);

        // 1. 滑点档位 + 分配（30% 营销 / 30% 分红池 / 40% 销毁）
        uint256 rate = getCurrentSlippage();
        uint256 slip = zytGross * rate / 10000;
        uint256 netZyt = zytGross - slip;
        uint256 slipMarket = slip * 3000 / 10000;
        uint256 slipDiv = slip * 3000 / 10000;
        uint256 slipBurn = slip - slipMarket - slipDiv;
        if (slipMarket > 0) IERC20(zytToken).transfer(config.marketAddress(), slipMarket);
        if (slipDiv > 0) {
            dividendPoolZyt += slipDiv;
            emit DividendAccrued(slipDiv);
        }
        if (slipBurn > 0) IZYTTokenBurn(zytToken).burnFrom(address(this), slipBurn);
        emit SlippageCollected(rate, slipMarket, slipDiv, slipBurn);

        // 2. 净额真实 swap（ZYT 净额进 pair，USDT 输出到本合约再转用户）
        IERC20(zytToken).transfer(pair, netZyt);
        usdtOut = UniV2Lib.getAmountOut(netZyt, zRes, uRes, config.swapFeeBps());
        require(usdtOut > 0, "Pool: zero out");
        _pairSwap(usdtOut, 0, address(this));
        IERC20(usdt).transfer(user, usdtOut);

        emit Sold(user, zytGross, slip, usdtOut);
    }

    /// @notice 转账税 30% 分红入池（仅 ZYTToken 调用，ZYT 已转入本合约）
    function accrueDividendZyt(uint256 amount) external {
        require(msg.sender == zytToken, "Pool: only token");
        if (amount > 0) {
            dividendPoolZyt += amount;
            emit DividendAccrued(amount);
        }
    }

    // ---------- 每日快照与通缩 ----------

    /// @notice 更新快照（Keeper 每日 08:01，由 Deflation 转调）
    function updateSnapshot() external onlyDeflation {
        (, uint256 uRes) = _reserves();
        snapshotPrice = getPrice();
        snapshotPoolUSDT = uRes;
        if (peakPoolUSDT < uRes) peakPoolUSDT = uRes;
        lastSnapshotAt = block.timestamp;
        emit SnapshotUpdated(snapshotPrice, uRes, block.timestamp);
    }

    /**
     * @notice 每日通缩：锁仓合约报销 2% 初始 LP → 抽出 ZYT_a/U_b。
     *         ZYT_a：1% 烧黑洞 + 1% 进分红池；U_b：直接转回 pair + sync
     *         （净效果只减池内 ZYT，池 U 不变，价格单边上行，不干扰滑点档位）。
     */
    function deflate() external onlyDeflation nonReentrant gated returns (uint256 burned, uint256 dividend) {
        (uint256 zRes, ) = _reserves();
        if (zRes <= config.deflationFloor()) return (0, 0);
        require(locker != address(0), "Pool: locker unset");

        // 1. 锁仓合约报销 LP 并把两侧资产转入本合约
        (uint256 zytA, uint256 usdtB) = ILocker(locker).skimDeflation(config.deflationLpRate());

        // 2. U 回池（sync，不组 LP）
        uint256 resynced = 0;
        if (usdtB > 0) {
            IERC20(usdt).transfer(pair, usdtB);
            IUniswapV2Pair(pair).sync();
            resynced = usdtB;
        }

        // 3. ZYT 分配：1% 烧 + 1% 分红
        if (zytA > 0) {
            uint256 burnPart = zytA / 2;
            uint256 divPart = zytA - burnPart;
            if (burnPart > 0) {
                IZYTTokenBurn(zytToken).burnFrom(address(this), burnPart);
                burned = burnPart;
            }
            if (divPart > 0) {
                dividendPoolZyt += divPart;
                dividend = divPart;
                emit DividendAccrued(divPart);
            }
        }
        emit Deflated(burned, dividend, resynced);
    }

    /// @notice 分红发放（ZYT，ZYTMining claimDividend 调用）
    function payoutDividend(address user, uint256 amount) external onlyMining {
        require(dividendPoolZyt >= amount, "Pool: div insufficient");
        dividendPoolZyt -= amount;
        IERC20(zytToken).transfer(user, amount);
    }

    // ---------- 内部 ----------

    /// @notice USDT → ZYT 真实 swap（先转入 pair 再 swap）
    function _swapUsdtForZyt(uint256 usdtIn, address to) internal returns (uint256 zytOut) {
        (uint256 zRes, uint256 uRes) = _reserves();
        zytOut = UniV2Lib.getAmountOut(usdtIn, uRes, zRes, config.swapFeeBps());
        require(zytOut > 0, "Pool: zero out");
        IERC20(usdt).transfer(pair, usdtIn);
        _pairSwap(0, zytOut, to);
    }

    /// @notice V2 addLiquidity（不经 Router：按最优比例转两侧进 pair 再 mint）
    /// @return liquidity LP 数量；zytUsed 实际入池的 ZYT（残留留在本合约由调用方处置）
    function _addLiquidity(uint256 usdtAmt, uint256 zytAmt, address to)
        internal
        returns (uint256 liquidity, uint256 zytUsed)
    {
        (uint256 zRes, uint256 uRes) = _reserves();
        uint256 zytOpt = zRes > 0 ? UniV2Lib.quote(usdtAmt, uRes, zRes) : zytAmt;
        uint256 usdtIn2;
        if (zytAmt >= zytOpt) {
            usdtIn2 = usdtAmt;
            zytUsed = zytOpt;
        } else {
            zytUsed = zytAmt;
            usdtIn2 = UniV2Lib.quote(zytAmt, zRes, uRes);
        }
        require(usdtIn2 <= usdtAmt && zytUsed <= zytAmt, "Pool: liquidity calc");
        if (usdtIn2 > 0) IERC20(usdt).transfer(pair, usdtIn2);
        if (zytUsed > 0) IERC20(zytToken).transfer(pair, zytUsed);
        liquidity = IUniswapV2Pair(pair).mint(to);
        require(liquidity > 0, "Pool: zero liquidity");
        _updatePeak(uRes + usdtIn2);
    }

    /// @notice pair.swap 封装（按 zytIsToken0 排序输出侧）
    function _pairSwap(uint256 usdtOut, uint256 zytOut, address to) internal {
        if (zytIsToken0) {
            IUniswapV2Pair(pair).swap(zytOut, usdtOut, to, "");
        } else {
            IUniswapV2Pair(pair).swap(usdtOut, zytOut, to, "");
        }
    }

    function _updatePeak(uint256 uRes) internal {
        if (peakPoolUSDT < uRes) peakPoolUSDT = uRes;
    }
}

/// @notice 锁仓合约接口（初始 LP 持有方）
interface ILocker {
    /// @notice 报销 rate 基点的初始 LP，removeLiquidity 后把两侧资产转给调用方（Pool）
    function skimDeflation(uint256 rateBps) external returns (uint256 zytAmt, uint256 usdtAmt);
}

/// @notice ZYT 销毁接口
interface IZYTTokenBurn {
    function burnFrom(address from, uint256 amount) external;
}

contracts/ZYTReferral.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ZYTReferral
 * @notice 推荐关系与 20 代分账（纯记账；奖励 mint 由 ZYTMining 执行）。
 *         1 代 7%、2-10 代各 2%、11-20 代各 0.5%、10% 技术运维。
 */
contract ZYTReferral is Ownable {
    address public mining;

    mapping(address => address) public referrerOf;   // 用户的直推上级
    mapping(address => uint256) public downlineCount; // 直推人数（= 可拿代数）

    event Bound(address indexed user, address indexed ref);

    modifier onlyMining() {
        require(msg.sender == mining, "Ref: only mining");
        _;
    }

    constructor() Ownable(msg.sender) {}

    function setMining(address _mining) external onlyOwner {
        mining = _mining;
    }

    /// @notice 绑定推荐关系（仅在未绑定、用户≠上级、且不形成循环时生效）
    /// @dev V3 修复：ref 的祖先链不得含 user（防 A→B→A 循环自我奖励）
    function bind(address user, address ref) external onlyMining {
        if (user == address(0) || ref == address(0) || user == ref) return;
        if (referrerOf[user] != address(0)) return;
        // 防循环：遍历 ref 的上级链（最多 20 代），若含 user 则拒绝绑定
        address cur = ref;
        for (uint256 i = 0; i < 20 && cur != address(0); i++) {
            if (cur == user) return;
            cur = referrerOf[cur];
        }
        referrerOf[user] = ref;
        downlineCount[ref]++;
        emit Bound(user, ref);
    }

    /// @notice 获取用户的上级链（从直推开始，最多 depth 代，空位为 0 地址）
    function getAncestors(address user, uint256 depth) public view returns (address[] memory) {
        address[] memory arr = new address[](depth);
        address cur = referrerOf[user];
        for (uint256 i = 0; i < depth && cur != address(0); i++) {
            arr[i] = cur;
            cur = referrerOf[cur];
        }
        return arr;
    }

    /// @notice 返回 user 在推荐树中的上溯链深（与"可拿代数=直推人数"规则无关，
    ///         可拿代数校验在 ZYTMining._distributeRef 中按 downlineCount(上级) 判定）
    function getDepth(address user) public view returns (uint256) {
        uint256 depth = 0;
        address cur = user;
        while (referrerOf[cur] != address(0) && depth < 20) {
            depth++;
            cur = referrerOf[cur];
        }
        return depth;
    }
}

contracts/ZYTToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "./ZYTConfig.sol";
import "./interfaces/IZYTForceSell.sol";

/**
 * @title ZYTToken（众赢币）
 * @notice v9 主代币。初始底池 21 亿枚由 Creator 一次铸出组真池，此后无任何 mint 路径。
 *         真池 gate 模式（唯一交易通道 = ZYTPoolManager）：
 *         - ZYT 流入 pair（卖出 / 加 LP）：require msg.sender 为 pool 或 creator（锁仓合约），
 *           用户无法直接向 pair 转 ZYT 卖出，也无法用 Router 绕过（Router 主动拉币时 msg.sender = Router 被拒）
 *         - ZYT 流出 pair（买入 / 通缩 removeLiquidity）：require pool.swapGate() 置位，
 *           gate 由 PoolManager 在 swap 前置位、后清位；用户直接在 Pancake 前端买币被拦
 *         - 用户间转账扣 10% 滑点（转账视同卖出）：30% 营销 / 30% 分红池 / 40% 销毁
 *         - P1-7 双向记账沿用：转出按快照价折算计入提取额，转入计入受赠额（堵静态 2 倍绕过）
 *         - P1-9 强卖基数沿用：checkAndBurn 用转账前余额
 *         - v7 卖出统计（UserSellInfo + userList）沿用：供 Ave/TP 审核与链下对账
 */
contract ZYTToken is ERC20, Ownable {
    address public minter;      // ZYTLiquidityCreator（仅建池 mint 一次）
    address public ledger;      // ZYTMining（P1-7 双向记账对象）
    address public pool;        // ZYTPoolManager（唯一 swap 通道 / 分红池载体）
    /// @dev 税分配内部转移标志（2026-09-25）：税分发（烧/营销/分红池）不再触发 _update hook，
    ///      防发送方转出折算重复计入（转出基数已含全额税，税内部分发若再折算会多计 30%×税率）
    bool private _inTax;
    address public forceSell;   // ZYTForceSell
    address public blackHole;
    address public configAddr;
    address public creator;     // 锁仓合约（= ZYTLiquidityCreator，持初始 LP）
    address public pairAddress; // ZYT/USDT 交易对（gate 判定用）

    mapping(address => bool) public isWhiteList; // 系统豁免（跳过税/记账/强卖 hook）

    // ---------- 卖出统计 ----------
    struct UserSellInfo {
        uint256 sellCount;
        uint256 totalSellZyt;
        uint256 totalSellUsdt;
        uint256 firstReceiveAt;
        uint256 lastSellAt;
        uint256 windowFlags;
    }
    mapping(address => UserSellInfo) public sellInfo;
    address[] public userList;
    mapping(address => uint256) public userIndex;

    event MinterChanged(address indexed minter);
    event LedgerChanged(address indexed ledger);
    event PoolChanged(address indexed pool);
    event ForceSellChanged(address indexed forceSell);
    event CreatorChanged(address indexed creator);
    event PairChanged(address indexed pair);
    event WhiteListSet(address indexed addr, bool enabled);
    event SellStatUpdated(address indexed user, uint256 zytAmount, uint256 usdtOut);

    modifier onlyMinter() {
        require(msg.sender == minter, "ZYT: not minter");
        _;
    }

    constructor(address blackHole_) ERC20("ZhongYing Token", "ZYT") Ownable(msg.sender) {
        require(blackHole_ != address(0), "ZYT: zero blackhole");
        blackHole = blackHole_;
    }

    function setMinter(address _minter) external onlyOwner {
        minter = _minter;
        emit MinterChanged(_minter);
    }

    function setLedger(address _ledger) external onlyOwner {
        ledger = _ledger;
        emit LedgerChanged(_ledger);
    }

    function setPool(address _pool) external onlyOwner {
        pool = _pool;
        emit PoolChanged(_pool);
    }

    function setForceSell(address _forceSell) external onlyOwner {
        forceSell = _forceSell;
        emit ForceSellChanged(_forceSell);
    }

    function setCreator(address _creator) external onlyOwner {
        creator = _creator;
        emit CreatorChanged(_creator);
    }

    function setPair(address _pair) external onlyOwner {
        pairAddress = _pair;
        emit PairChanged(_pair);
    }

    function setConfig(address _config) external onlyOwner {
        configAddr = _config;
    }

    function setWhiteList(address addr, bool enabled) external onlyOwner {
        isWhiteList[addr] = enabled;
        emit WhiteListSet(addr, enabled);
    }

    /// @notice 铸造（v9 仅 Creator 建池铸 21 亿一次，受 totalSupplyCap 保险丝限制）
    function mintTo(address to, uint256 amount) external onlyMinter {
        require(
            configAddr != address(0) && totalSupply() + amount <= ZYTConfig(configAddr).totalSupplyCap(),
            "ZYT: supply cap"
        );
        _mint(to, amount);
    }

    /// @notice 销毁（滑点 40% 黑洞 / 强制卖出 / 每日通缩 1%）
    function burnFrom(address from, uint256 amount) external {
        require(msg.sender == pool || msg.sender == forceSell, "ZYT: not burner");
        _burn(from, amount);
    }

    /// @notice 记录卖出 USDT 折合（ZYTMining.sellZyt 调用）
    function recordSellUsdt(address seller, uint256 usdtOut) external {
        require(msg.sender == ledger, "ZYT: not ledger");
        sellInfo[seller].totalSellUsdt += usdtOut;
        emit SellStatUpdated(seller, 0, usdtOut);
    }

    function getUserCount() external view returns (uint256) {
        return userList.length;
    }

    function getUserAt(uint256 i) external view returns (address) {
        return userList[i];
    }

    function getSellInfo(address user)
        external
        view
        returns (uint256 sellCount, uint256 totalSellZyt, uint256 totalSellUsdt, uint256 firstReceiveAt, uint256 lastSellAt, uint256 windowFlags)
    {
        UserSellInfo storage s = sellInfo[user];
        return (s.sellCount, s.totalSellZyt, s.totalSellUsdt, s.firstReceiveAt, s.lastSellAt, s.windowFlags);
    }

    function _update(address from, address to, uint256 amount) internal override {
        super._update(from, to, amount);

        // 税分配内部转移：跳过全部 hook（金额已含在发送方转出折算基数里，防重复记账/统计/强卖触发）
        if (_inTax) return;

        // 铸币：接收方启动强卖计时（v9 仅 creator 铸币，creator 为白名单，实际不触发）
        if (from == address(0)) {
            if (to != address(0) && !isWhiteList[to]) {
                _onReceive(to);
            }
            return;
        }
        // 销毁：无 hook
        if (to == address(0)) return;

        bool fromPair = from == pairAddress;
        bool toPair = to == pairAddress;

        if (toPair) {
            // ---- 卖闸：ZYT 流入 pair，仅 pool（卖出/加 LP）或 creator 允许 ----
            require(msg.sender == pool || msg.sender == creator, "ZYT: pair inflow gated");
            if (!isWhiteList[from]) {
                // 真实卖出计入强卖进度（P1-9 语义沿用：转账前余额为基数）
                if (forceSell != address(0)) {
                    uint256 burnAmount = IZYTForceSell(forceSell).checkAndBurn(from, to, amount);
                    if (burnAmount > 0) _burn(from, burnAmount);
                }
                _recordSell(from, amount);
            }
            return;
        }

        if (fromPair) {
            // ---- 买闸：ZYT 流出 pair，要求 pool 的 swapGate 置位（买币/通缩抽池均由 pool 发起）----
            require(pool != address(0) && IPoolGate(pool).swapGate(), "ZYT: pair outflow gated");
            if (!isWhiteList[to]) {
                // 买币到账：启动强卖计时（不计受赠额，买币成本不抬高静态上限）
                _onReceive(to);
            }
            return;
        }

        // ---- 普通转账 ----
        if (isWhiteList[from]) {
            // 系统路径（pool 分红转出 / creator 建池等）：接收方启动强卖计时，
            // 不计受赠额（分红/买币类系统转入不抬高静态上限，受赠额只来自用户间转账）
            if (!isWhiteList[to]) {
                _onReceive(to);
            }
            return;
        }
        if (isWhiteList[to]) {
            // 用户转给系统地址（卖出路径 user→pool 等）：无转账税（防止 _distributeTax
            // 内部 _transfer 递归到白名单分支重复收税），按转出处理记账/强卖/统计。
            // 2026-09-24 双计修复：to == pool 的转移必然是 Mining.sellZyt 卖出流程
            // （pool 先拉币再 swap），提取记账由 Mining 实收单点完成（withdrawTotal += usdtOut），
            // 此处再折算会导致同一笔卖出双计（实测 1.0363 + 0.9819 = 2.0182）。
            // 用户直转 pool 无收益（币滞留池合约），无套利通道；其余系统地址（market 等）保留折算。
            if (forceSell != address(0)) {
                uint256 burnAmount = IZYTForceSell(forceSell).checkAndBurn(from, to, amount);
                if (burnAmount > 0) _burn(from, burnAmount);
            }
            _recordSell(from, amount);
            if (ledger != address(0) && to != pool) {
                IZYTMiningLedger(ledger).recordTransferOut(from, amount);
            }
            return;
        }

        // 双方均非白名单的用户间转账（转账视同卖出）
        uint256 tax2 = configAddr != address(0)
            ? amount * ZYTConfig(configAddr).transferSlippage() / 10000
            : 0;
        // 1. 强卖 hook + 卖出统计（基数 = amount，与 v8 P1-9「转账前余额」口径精确一致：
        //    checkAndBurn 时刻余额已扣 amount、未扣税，bal = balanceOf + amount = 转账前余额）
        if (forceSell != address(0)) {
            uint256 burnAmount = IZYTForceSell(forceSell).checkAndBurn(from, to, amount);
            if (burnAmount > 0) _burn(from, burnAmount);
        }
        _recordSell(from, amount);
        // 接收方首收登记（强卖窗口起点 + 用户列表；普通转账路径）
        if (!isWhiteList[to]) _onReceive(to);
        // 2. P1-7 记账（基数 = amount + tax，转出总量计入提取额，防绕过口径从严）
        if (ledger != address(0)) {
            IZYTMiningLedger(ledger).recordTransferOut(from, amount + tax2);
            IZYTMiningLedger(ledger).recordTransferIn(to, amount); // 接收方实收（税从发送方另扣）
        }
        // 3. 执行税（放最后：不影响 checkAndBurn 读到的余额）
        if (tax2 > 0) _distributeTax(from, tax2);
    }

    /// @notice 转账税分配：40% 销毁 + 30% 营销 + 30% 分红池
    function _distributeTax(address from, uint256 tax) internal {
        uint256 burnPart = tax * 4000 / 10000;
        uint256 marketPart = tax * 3000 / 10000;
        uint256 divPart = tax - burnPart - marketPart;
        // 2026-09-25：分发期间置位，_update hook 全部跳过（发送方转出折算只算一次全额含税）
        _inTax = true;
        if (burnPart > 0) _burn(from, burnPart);
        if (marketPart > 0 && configAddr != address(0)) {
            address market = ZYTConfig(configAddr).marketAddress();
            if (market != address(0)) _transfer(from, market, marketPart);
        }
        if (divPart > 0 && pool != address(0)) {
            _transfer(from, pool, divPart);
            IPoolTax(pool).accrueDividendZyt(divPart);
        }
        _inTax = false;
    }

    /// @notice 接收方首次收币：启动强卖窗口 + 入用户列表（幂等）
    function _onReceive(address to) internal {
        if (forceSell != address(0)) {
            IZYTForceSell(forceSell).onMint(to, 0);
        }
        if (sellInfo[to].firstReceiveAt == 0) {
            sellInfo[to].firstReceiveAt = block.timestamp;
            _addToUserList(to);
        }
    }

    /// @notice 卖出统计（卖出/转出次数、累计量、首收、入列表）
    function _recordSell(address from, uint256 amount) internal {
        UserSellInfo storage s = sellInfo[from];
        s.sellCount += 1;
        s.totalSellZyt += amount;
        s.lastSellAt = block.timestamp;
        if (s.firstReceiveAt == 0) {
            s.firstReceiveAt = block.timestamp;
        }
        _addToUserList(from);
        emit SellStatUpdated(from, amount, 0);
    }

    function _addToUserList(address addr) internal {
        if (userIndex[addr] == 0) {
            userList.push(addr);
            userIndex[addr] = userList.length;
        }
    }
}

/// @notice PoolManager 的 swap 闸门（买币/通缩抽池期间置位）
interface IPoolGate {
    function swapGate() external view returns (bool);
}

/// @notice PoolManager 的转账税分红入账（30% 部分）
interface IPoolTax {
    function accrueDividendZyt(uint256 amount) external;
}

/// @notice P1-7：ZYTMining 侧的折算记账接口（仅 ZYTToken 可调用）
interface IZYTMiningLedger {
    function recordTransferOut(address user, uint256 zytAmount) external;
    function recordTransferIn(address user, uint256 zytAmount) external;
}
